import re, math
fn='/app/text.gcode'
cmd_re=re.compile(r'^([GM])(\d+(?:\.\d+)?)(?:\s+(.*))?$')
word_re=re.compile(r'([A-Za-z])([-+]?\d*\.?\d+)')
pos={'X':0.0,'Y':0.0,'Z':0.0}
cur=None
segs=[]
for line in open(fn,errors='replace'):
    line=line.split(';',1)[0].strip()
    m=cmd_re.match(line)
    if not m: continue
    typ,num,rest=m.group(1),float(m.group(2)),m.group(3) or ''
    words={k:float(v) for k,v in word_re.findall(rest)}
    if typ=='M' and num==486:
        if 'S' in words: cur=int(words['S'])
        continue
    if typ=='G' and num in (0,1):
        new={a:words.get(a,pos[a]) for a in ('X','Y','Z')}
        de=words.get('E',0.0)  # M83 relative extrusion throughout
        if cur==0 and de>0 and any(abs(new[a]-pos[a])>1e-7 for a in ('X','Y','Z')):
            segs.append((pos['X'],pos['Y'],new['X'],new['Y']))
        pos=new

xs=[v for s in segs for v in (s[0],s[2])]
ys=[v for s in segs for v in (s[1],s[3])]
x0,x1=min(xs),max(xs); y0,y1=min(ys),max(ys)
scale=2.0
W=int(math.ceil((x1-x0)*scale))+1
H=int(math.ceil((y1-y0)*scale))+1
pix=[[0]*W for _ in range(H)]

def plot(x,y):
    xi=round((x-x0)*scale); yi=round((y-y0)*scale)
    if 0<=xi<W and 0<=yi<H: pix[yi][xi]=1

for x_a,y_a,x_b,y_b in segs:
    ax=round((x_a-x0)*scale); ay=round((y_a-y0)*scale)
    bx=round((x_b-x0)*scale); by=round((y_b-y0)*scale)
    dx=abs(bx-ax); dy=-abs(by-ay); sx=1 if ax<bx else -1; sy=1 if ay<by else -1
    err=dx+dy
    while True:
        if 0<=ax<W and 0<=ay<H: pix[ay][ax]=1
        if ax==bx and ay==by: break
        e2=2*err
        if e2>=dy: err+=dy; ax+=sx
        if e2<=dx: err+=dx; ay+=sy

# Add immediate neighbors so thin diagonal strokes remain connected/visible.
base=[row[:] for row in pix]
for y,row in enumerate(base):
    for x,v in enumerate(row):
        if v:
            for yy in range(max(0,y-1),min(H,y+2)):
                for xx in range(max(0,x-1),min(W,x+2)):
                    pix[yy][xx]=1

def braille(flip_y=False):
    out=[]
    for cy in range(0,H,4):
        row=''
        for cx in range(0,W,2):
            code=0
            for dy in range(4):
                for dx in range(2):
                    y=H-1-(cy+dy) if flip_y else cy+dy
                    if 0<=y<H and 0<=cx+dx<W and pix[y][cx+dx]:
                        code |= 1 << (dy*2+dx)
            row+=chr(0x2800+code)
        out.append(row.rstrip(chr(0x2800)))
    while out and not out[-1]: out.pop()
    return '\n'.join(out)

print(f'{len(segs)} segments; bounds X {x0:.3f}..{x1:.3f}, Y {y0:.3f}..{y1:.3f}; raster {W}x{H}')
print('\n=== Y INCREASING UPWARD (standard plot orientation) ===')
print(braille(False))
print('\n=== Y INCREASING DOWNWARD (printer top-view orientation) ===')
print(braille(True))
