cmd=re.compile(r'^([GM])(\d+(?:\.\d+)?)(?:\s+(.*))?$')
word=re.compile(r'([A-Za-z])([-+]?\d*\.?\d+)')
pos={'X':0.,'Y':0.,'Z':0.}; obj=None; f=0
chains=[]; cur=[]; last_endpoint=None

def dist3(a,b): return math.dist(a,b)
def flush():
 global cur
 if cur:
  chains.append(cur); cur=[]
for n,line in enumerate(open(fn),1):
 line=line.split(';',1)[0].strip(); m=cmd.match(line)
 if not m: continue
 typ,num,rest=m.group(1),float(m.group(2)),m.group(3) or ''; w={k:float(v) for k,v in word.findall(rest)}
 if typ=='M' and num==486 and 'S' in w:
  flush(); obj=int(w['S']); continue
 if typ=='G' and num in (0,1):
  if 'F' in w: f=w['F']
  old=(pos['X'],pos['Y'],pos['Z']); new=tuple(w.get(a,pos[a]) for a in ('X','Y','Z')); de=w.get('E',0.)
  moved=dist3(old,new)>1e-7
  if obj==0 and de>0 and moved:
   if cur and dist3(cur[-1][1],old)>0.01: flush()
   cur.append((n,old,new,de,f))
  elif moved or de<0:
   flush()
  pos={'X':new[0],'Y':new[1],'Z':new[2]}
flush()
print('chains',len(chains))
stats=collections.Counter(); examples=[]
prepared=[]
for c in chains:
 pts=[c[0][1]]+[x[2] for x in c]
 length=sum(math.dist(a[2],a[1]) for a in c)
 closure=math.dist(pts[0],pts[-1])
 closed=closure<0.08
 stats['closed' if closed else 'open']+=1
 if closed:
  xs=[p[0] for p in pts]; ys=[p[1] for p in pts]; zs=[p[2] for p in pts]
  prepared.append((c,pts,length,closure,(min(xs),max(xs),min(ys),max(ys),min(zs),max(zs))))
  if len(examples)<15: examples.append((len(c),length,closure,pts[0],pts[-1],(min(xs),max(xs),min(ys),max(ys))))
print('stats',dict(stats))
print('closed examples: command_count length closure start end bbox')
for x in examples: print(x)
print('closed length distribution:')
for lo,hi in [(0,.2),(.2,.5),(.5,1),(1,2),(2,5),(5,10),(10,20),(20,100000)]:
 print(lo,hi,sum(1 for x in prepared if lo<=x[2]<hi))
